import registry from './Data/regions.json' with { type: 'json' };
// Region registry: countries (code, name, labels, search aliases), coast chunks, heightmap tiles and place files.
// Data/regions.json is generated by scripts/build_regions.py; add a country there instead of in the game code.

export const REGIONS = registry;
export const COUNTRIES = registry.countries;   // display order: stamp book, search groups
export const COUNTRY_ORDER = COUNTRIES.map((country) => country.name);
const byCode = new Map(COUNTRIES.map((country) => [country.code, country]));
const byName = new Map(COUNTRIES.map((country) => [country.name, country]));
export const countryByCode = (code) => byCode.get(code) ?? null;
// a land code ('jp') or a display name ('日本') -> code, or the input unchanged when it is neither
export const countryCode = (country) => byCode.has(country) ? country : byName.get(country)?.code ?? country;
export const countryName = (code) => byCode.get(code)?.name ?? code;
export const COUNTRY_NAMES = Object.fromEntries(COUNTRIES.map(({ code, name }) => [code, name]));

const { exaggeration } = registry;
// Vertical exaggeration of terrain relief: stronger where the registry asks for it (Taiwan's ranges are the main show).
export function exaggerationAt(latitude, longitude) {
  for (const { bounds: [lon0, lat0, lon1, lat1], value } of exaggeration.areas) {
    if (latitude > lat0 && latitude < lat1 && longitude > lon0 && longitude < lon1) return value;
  }
  return exaggeration.default;
}
